from __future__ import absolute_import
import re
from .base_parser import CommonStatCommandParser, ParserBase


class StatCommonParserGaia(CommonStatCommandParser):
    def __init__(self, raw_output):
        super(StatCommonParserGaia, self).__init__(raw_output)
        self.resource_per_antenna = {}
        self.tech_per_antenna = {}
        self._prepare_data()

    def _parse_carrier_by_tx(self):
        carrier_data = {
            value: {
                "state": self._channel_status[index],
                "frequency": self._frequency[index],
                "type": self._channel_type[index],
                "bandwidth": self._bandwidth[index],
                "resource": self._resource[index],
            }
            for index, value in enumerate(self._tx_list)
        }
        return carrier_data

    def _prepare_data(self):
        for line in self.raw_output.splitlines():
            antenna = re.match(r"\s*ANT:\s(?P<number_a>\d{1,2})", line)
            if antenna:
                self.antenna_id = "ANT{}".format(antenna.group("number_a"))
            trx_re = re.match(r".*Uoam ID\s*:", line)
            if trx_re:
                self._tx_per_antenna.setdefault(
                    self.antenna_id, line[trx_re.end():].split()[:-1]
                )
                self._tx_list.extend(line[trx_re.end():].split()[:-1])

            self._check_state(line)
            self._check_frequency(line)
            self._check_type(line)
            self._check_bandwidth(line)
            self._check_resource(line)

    def _check_state(self, line):
        if re.match(r"\s*state\s*:", line):
            self._channel_status.extend(line[line.index(":") + 1:].split()[:-1])

    def _check_frequency(self, line):
        if re.match(r"\s*frequency\[MHz].*:", line):
            self._frequency.extend(line[line.index(":") + 1:].split()[:-1])

    def _check_type(self, line):
        if re.match(r"\s*type.*:", line):
            self._channel_type.extend(line[line.index(":") + 1:].split()[:-1])
            self.tech_per_antenna.setdefault(
                self.antenna_id[3:], line[line.index(":") + 1:].split()[:-1]
            )

    def _check_bandwidth(self, line):
        if re.match(r"\s*bandwidth.*:", line):
            self._bandwidth.extend(line[line.index(":") + 1:].split()[:-1])

    def _check_resource(self, line):
        if re.match(r"\s*resource.*", line):
            self._resource.extend(line[line.index(":") + 1:].split()[:-1])
            self.resource_per_antenna.setdefault(
                self.antenna_id[3:], line[line.index(":") + 1:].split()[:-1]
            )


class TxStatGAIA(StatCommonParserGaia):
    def __init__(self, raw_output):
        super(TxStatGAIA, self).__init__(raw_output)
        self.tx_per_tech = {}

    def get_tx_per_technology(self):
        """
        Return map tx per technology (GSM, WCDMA, LTE).

        :return: tx per technology
        :rtype: dict
        """
        for antenna, resources in self.resource_per_antenna.items():
            self._sort_tx_per_tech(antenna, resources, self.tech_per_antenna[antenna])
        return self.tx_per_tech

    def _sort_tx_per_tech(self, antenna, resources, technology):
        for resource in resources:
            self.tx_per_tech.setdefault(
                "{}/{}".format(antenna, resource), technology[resources.index(resource)]
            )


class RxStatGAIA(StatCommonParserGaia):
    def __init__(self, raw_output):
        super(RxStatGAIA, self).__init__(raw_output)


class FrontEndGainGAIA(ParserBase):
    def __init__(self, raw_output):
        super(FrontEndGainGAIA, self).__init__(raw_output)

    def parse_front_end_gain(self):
        """
        Parse 'frontEnd feGetLnaGain 2 2' command output.

        :return: front end gain in format {antenna: front end gain}
        :rtype: int
        """
        return int(re.search(r"gain:\s([\d]{1,})", self.raw_output).group(1))


class TxPowerGAIA(ParserBase):
    def __init__(self, raw_output):
        super(TxPowerGAIA, self).__init__(raw_output)

    def parse_tx_power(self):
        """
        Parse 'rfctrl txPower' command output.

        :return: tx power data
        :rtype: dict
        """
        tx_power_dict = {}
        for line in self.raw_output.splitlines():
            resource = re.match(r":\s{2}resource\s{2}:\s*([\d]{1,2}/[\d]{1,2}.*)", line)
            antenna = re.match(
                r":\sANT(?P<antenna_no>[\d]{1,2})\s\[dBm\]\s:\s*(?P<antenna_power>.*)",
                line,
            )
            if resource:
                tx_power_dict.setdefault("resource", []).extend(
                    resource.group(1).split()
                )
            if antenna:
                tx_power_dict.setdefault(
                    "{}".format(antenna.group("antenna_no")), []
                ).extend(antenna.group("antenna_power").split())
        return tx_power_dict


class RxPowerGAIA(ParserBase):
    def __init__(self, raw_output):
        super(RxPowerGAIA, self).__init__(raw_output)

    def parse_rx_power(self):
        """
        Parse 'rfctrl rxPower' command output.

        :return: rx power data
        :rtype: dict
        """
        rx_power_dict = {}
        for line in self.raw_output.splitlines():
            resource = re.match(r":\s*<NCO>\s*:\s*([\d]{1,2}/[\d]{1,2}.*)", line)
            antenna = re.match(
                r":\sANT(?P<antenna_no>[\d]{1,2})\s\[dBm\]\[resource\]\s:\s*(?P<antenna_power>.*)",
                line,
            )
            if resource:
                rx_power_dict.setdefault("resource", []).extend(
                    resource.group(1).split()
                )
            if antenna:
                rx_power_dict.setdefault(
                    "{}".format(antenna.group("antenna_no")), []
                ).extend(antenna.group("antenna_power").split())
        return rx_power_dict
